package vn.cinema;
import org.junit.jupiter.api.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.beans.factory.annotation.Autowired;import vn.cinema.app.Application;import vn.cinema.service.AuthService;import vn.cinema.dto.AuthRequests.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(classes=Application.class) class AuthTest{@Autowired AuthService service;@Test void registerDuplicateLoginWrongPassword(){String email="test"+System.nanoTime()+"@example.com";var r=new Register("Khách",email,"123456","0900000000");var user=service.register(r);assertThat(user.id).isNotNull();assertThat(user.role).isEqualTo("USER");assertThatThrownBy(()->service.register(r)).hasMessageContaining("Email");assertThat(service.login(new Login(email,"123456"))).containsKey("token");assertThatThrownBy(()->service.login(new Login(email,"wrong"))).hasMessageContaining("mật khẩu");}}